/// <summary>
/// Service to synchronize and log changes in query store query hints.
/// </summary>
public class DBMSQLQueryStoreQueryHintSyncService extends SysOperationServiceBase
{
}

Method.Source:
/// <summary>
/// Synchronizes current query hints view with previous snapshot, logs changes, and updates snapshot.
/// </summary>
public void process()
{
    DBMSQLQueryStoreQueryHints hintsView;
    DBMSQLQueryStoreQuery queryView;
    DBMSQLQueryStoreQueryHintSnapshot snapshotTable;
    DBMSQLQueryStoreQueryHintLog logTable;

    DatabaseLogType changeTypeInsert = DatabaseLogType::Insert;
    DatabaseLogType changeTypeDelete = DatabaseLogType::Delete;

    ttsbegin;

    // 1. Detect and log INSERT changes (new hints in hintsView that do not exist in snapshot)
    insert_recordset logTable (QueryHintId, QueryId, QueryHintText, ChangeType, QueryHash)
        select QueryHintId, QueryId, QueryHintText, changeTypeInsert from hintsView
            join QueryHash from queryView
            where queryView.QueryId == hintsView.QueryId
            notexists join snapshotTable
            where snapshotTable.QueryHintId == hintsView.QueryHintId;

    // 2. Detect and log DELETE changes (hints in snapshot that no longer exist in hintsView)
    insert_recordset logTable (QueryHintId, QueryId, QueryHintText, QueryHash, ChangeType)
        select QueryHintId, QueryId, QueryHintText, QueryHash, changeTypeDelete from snapshotTable
            notexists join hintsView
            where hintsView.QueryHintId == snapshotTable.QueryHintId;

    // 3. Update snapshot table with current hints
    delete_from snapshotTable;

    insert_recordset snapshotTable (QueryHintId, QueryId, QueryHintText, QueryHash)
        select QueryHintId, QueryId, QueryHintText from hintsView
            join QueryHash from queryView
            where queryView.QueryId == hintsView.QueryId;

    // 4. Clean up log records for query IDs that no longer exist in the main query store table
    delete_from logTable
        notexists join queryView
        where queryView.QueryId == logTable.QueryId;

    ttscommit;
}
